//! Compliance catalog: control tags → OSCAL controls → candidate operations.
//!
//! Table is `oscal/TAG-TAXONOMY.md` as code; `oscal/catalogs/etched-catalog`
//! is authoritative for controls and the sealed blobs (`opblob inspect`)
//! for method names and capabilities. Qualifier tags (`action:*`,
//! `approval:*`, `surface:*`, `data:*`, `model:*`) never match controls —
//! they steer the decision.

use crate::model::Operation;

/// One taxonomy row: tag, control, and candidate `(plugin, method,
/// sealed capability)` triples. Capability is `None` when no blob is
/// sealed for the method yet (e.g. `web3` anchor: drafts only).
/// `(plugin, sealed method, sealed capability or None if unsealed)`.
pub type SealedOp = (&'static str, &'static str, Option<&'static str>);
/// `(control tag, OSCAL control, candidate sealed operations)`.
pub type TaxonomyRow = (&'static str, &'static str, &'static [SealedOp]);
const TAXONOMY: &[TaxonomyRow] = &[
    ( … ),
    ( … ),
    ( … ),
    ( … ),
    ( … ),
];

/// The taxonomy table as data: tag, control, candidate operations.
/// Spec builders consume this; `match_controls` remains the routing view.
pub fn taxonomy() -> &'static [TaxonomyRow] {
    TAXONOMY
}

/// A control the request matched, with its candidate operations.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ControlMatch { … }
fn seal_operation(spec: &(&str, &str, Option<&str>)) -> Operation { … }

/// Resolve request tags to controls, keeping taxonomy order and dropping
/// controls outside the profile. Unknown control tags match nothing —
/// a tag miss is a refusal downstream, never a default-allow.
pub fn match_controls(tags: &[String], profile_controls: &[String]) -> Vec<ControlMatch> { … }

/// True when the request carries the two-person-rule marker.
pub fn is_root(tags: &[String]) -> bool {
    tags.iter().any(|t| t == "approval:root")
}

#[cfg(test)]
mod tests { … }

//! Spec generator: trim rows to a renderable grants-console spec.
//!
//! The console is a generated spec, not a hand-built page: every element is
//! a catalog component, validated before rendering, actions call granted
//! methods only. The propose form is illustrative (`dashboardFormPreview`
//! submits nothing) — proposals travel the approval path, never the UI.

use serde_json::{json, Value};

/// One grant row: the unit the console table renders.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GrantRow { … }
pub const ALLOWED_COMPONENTS: &[&str] = &[ … ];

/// Build the flat-spec console for `rows`.
pub fn console_spec(title: &str, subtitle: &str, rows: &[GrantRow]) -> Value { … }

#[cfg(test)]
mod tests { … }

/// Build the barebones taxonomy picker spec from the OSCAL table.
/// Read-only draft: tag → control → operation → capability. A `None`
/// capability renders as unsealed; the table never grants anything.
pub fn taxonomy_spec(title: &str, subtitle: &str) -> Value { … }

#[cfg(test)]
mod taxonomy_tests { … }

/// One provenance row: why a member holds a capability.
pub struct ProvenanceRow { … }

/// Provenance view: capability <- role <- position <- chart event.
pub fn provenance_spec(title: &str, rows: &[ProvenanceRow]) -> Value { … }

/// One chart node: id, label, parent id or `None` for roots.
pub struct ChartNode { … }

/// Org-chart viewer: topology (reports-to edges) plus a role table.
/// Layout is deterministic: depth sets x, sibling order sets y.
pub fn orgchart_spec(title: &str, nodes: &[ChartNode]) -> Value { … }

/// One feed episode: id, trigger, outcome, vectorized and purged flags.
pub struct FeedEpisode { … }

/// Feed-loop monitor: status, episode event log, vectorize/purge table.
pub fn feed_spec(title: &str, episodes: &[FeedEpisode]) -> Value { … }

#[cfg(test)]
mod builder_tests { … }

