70:          >{runtime.routeConfirmed
71:            ? selectionLabel(runtime.route, runtime.providers)
72:            : "Choose a model and apply to confirm the route."}
73:        </p>
74:        <p class="route-status" role="status" aria-live="polite">
75:          {runtime.routePending
76:            ? `Applying ${selectionLabel(runtime.routeAttempt ?? draft, runtime.providers)}`
77:            : changed
78:              ? `Pending: ${selectionLabel(draft, runtime.providers)}`
79:              : runtime.adapter.kind === "local"
80:                ? "Local selection · no network calls"
