async function apply(requested: RouteSelection = draft) {
  if (!control || !access || pending || unconfirmed || !valid || !alive) return;
  if (current && sameSelection(current, requested)) return;
  pending = true;
  accepted = false;
  error = null;
  try {
    await control.set(requested, async (...args) => {
      if (!alive) throw new Error("Model selection context changed.");
      await elevation.elevate(...args);
      if (!alive) throw new Error("Model selection context changed.");
    });
  } catch (e) {
    if (alive) {
      pending = false;
      unconfirmed = e instanceof ControlPlaneMutationUnconfirmedError;
      error =
