import Harness from "../test/fixtures/Harness.svelte";
import { act, cleanup, fireEvent, render, screen } from "../test/native";
import { afterEach, describe, expect, it, vi } from "vitest";
import type { ChatAdapter } from "./chat-adapter";
import { createLocalChatAdapter } from "./local-chat-adapter";

const providers = [
  { id: "one", label: "One", models: [{ id: "old", label: "Old", detail: "" }] },
  { id: "two", label: "Two", models: [{ id: "first", label: "First", detail: "" }, { id: "wanted", label: "Wanted", detail: "" }] },
];

afterEach(cleanup);

describe("debug", () => {
  it("traces provider then model change", async () => {
    const selectRoute = vi.fn(async (s: unknown) => s);
    const adapter = { ...createLocalChatAdapter(), kind: "remote", providers, selectRoute } as ChatAdapter;
    render(Harness, { adapter, view: "picker" });
    fireEvent.click(screen.getByText("Personal context"));
    const providerBox = screen.getByRole("combobox", { name: "Provider" });
    const modelBox = () => screen.getByRole("combobox", { name: "Model" });
    console.log("BEFORE provider options:", providerBox.innerHTML.length, "model value:", (modelBox() as HTMLSelectElement).value);
    fireEvent.change(providerBox, { target: { value: "two" } });
    console.log("AFTER provider model value:", (modelBox() as HTMLSelectElement).value, "model inner:", modelBox().innerHTML.slice(0, 200));
    await act(async () => {});
    console.log("AFTER flush model value:", (modelBox() as HTMLSelectElement).value);
    console.log("selectRoute calls after provider:", selectRoute.mock.calls.length);
    fireEvent.change(modelBox(), { target: { value: "wanted" } });
    await act(async () => {});
    console.log("selectRoute calls after model:", JSON.stringify(selectRoute.mock.calls));
    expect(true).toBe(true);
  });
});

