//! Browser reachability for the existing, identity-gated EMQX wake doorbell.
//!
//! This is a byte relay on the already trusted :8090 TLS ingress. EMQX still
//! authenticates every MQTT CONNECT through ExHook and authorizes the exact
//! owner topic. The relay cannot select a broker, topic, or credential.

use std::{io::BufReader, net::Ipv4Addr, sync::Arc, time::Duration};

use axum::{
    extract::{
        Extension,
        ws::{Message as BrowserMessage, WebSocket, WebSocketUpgrade},
    },
    http::{HeaderMap, StatusCode, header},
    response::{IntoResponse, Response},
};
use futures::{SinkExt, StreamExt};
use tokio::net::TcpStream;
use tokio::sync::OnceCell;
use tokio_rustls::{TlsConnector, rustls};
use tokio_tungstenite::{WebSocketStream, tungstenite, tungstenite::protocol::WebSocketConfig};

pub(crate) const PUBLIC_LISTENER: &str = "wss://10.0.0.2:8090/mqtt";
const BROKER_HOST: &str = op_plugins::state_plugins::emqx::EMQX_MQTT_WSS_HOST;
const BROKER_PORT: u16 = op_plugins::state_plugins::emqx::EMQX_MQTT_WSS_PORT;
const BROKER_CA: &str = "/etc/op-dbus/tls/tonic-svc0-ca.crt";
const CONNECT_TIMEOUT: Duration = Duration::from_secs(5);
const FIRST_CONNECT_TIMEOUT: Duration = Duration::from_secs(10);
const IDLE_TIMEOUT: Duration = Duration::from_secs(90);
const SEND_TIMEOUT: Duration = Duration::from_secs(5);
const MAX_FRAME_BYTES: usize = 64 * 1024;
static BROKER_TLS: OnceCell<Arc<rustls::ClientConfig>> = OnceCell::const_new();

fn allowed_origin(headers: &HeaderMap) -> bool {
    matches!(
        headers
            .get(header::ORIGIN)
            .and_then(|value| value.to_str().ok()),
        Some("http://dashboard.ghostbridge.tech:8080") | Some("http://10.0.0.2:8080")
    )
}

fn mqtt_subprotocol(headers: &HeaderMap) -> bool {
    headers
        .get(header::SEC_WEBSOCKET_PROTOCOL)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.split(',').any(|part| part.trim() == "mqtt"))
}

/// The browser authenticates to EMQX after this upgrade with its own SID1 or
/// OIA1 MQTT password. Never inspect or log MQTT frames here.
pub(crate) async fn upgrade(
    ws: WebSocketUpgrade,
    headers: HeaderMap,
    Extension(permit): Extension<Arc<tokio::sync::OwnedSemaphorePermit>>,
) -> Response {
    if !allowed_origin(&headers) || !mqtt_subprotocol(&headers) {
        return StatusCode::FORBIDDEN.into_response();
    }
    let broker = match tokio::time::timeout(CONNECT_TIMEOUT, connect_broker()).await {
        Ok(Ok(broker)) => broker,
        _ => return StatusCode::BAD_GATEWAY.into_response(),
    };
    accept_upgrade(ws, broker, Some(permit))
}

fn accept_upgrade<S>(
    ws: WebSocketUpgrade,
    broker: WebSocketStream<S>,
    permit: Option<Arc<tokio::sync::OwnedSemaphorePermit>>,
) -> Response
where
    S: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + Send + 'static,
{
    ws.protocols(["mqtt"])
        .max_message_size(MAX_FRAME_BYTES)
        .max_frame_size(MAX_FRAME_BYTES)
        .on_upgrade(move |browser| async move {
…
        })
        .into_response()
}

    let api_routes = Router::new()
…
        .route(
            "/privacy/credentials",
            post(handlers::privacy::set_credentials),
        )
        // Google OAuth endpoints
        .route("/privacy/google/auth", get(handlers::privacy::google_auth))
        .route(
            "/privacy/google/callback",
            get(handlers::privacy::google_callback),
        );

    // WebSocket route
    let ws_route = Router::new().route("/ws", get(websocket::websocket_handler));

    // Main dashboard/REST router. MCP and gRPC are served only by the
    // authenticated bridge on TLS :8090; op-web forwards the page's gRPC-Web
    // calls to it unchanged (`door_proxy`).
    let router = Router::new()
        .nest("/api", api_routes)
        // Ordinary HTTP compatibility lives on op-web :8080. Each handler is
        // an adapter to a schema-declared bridge method on gRPC :8090.
        .route(
            "/v1/models",
            get(handlers::chat_router::openai_models_handler),
        )
        .route(
            "/v1/chat/completions",
            post(handlers::chat_router::chat_router_chat_handler),
        )
        // Human-facing privacy verification flow (magic-link target)
        .route(
            "/privacy/verify",
            get(handlers::privacy::verify_redirect)
                .route_layer(axum::middleware::from_fn(security::no_store)),
        )
        .route(
            "/privacy/access",
            get(handlers::privacy::privacy_access_message)
                .route_layer(axum::middleware::from_fn(security::no_store)),
        )
        .merge(ws_route)
        .nest("/groups-admin", groups_admin::create_groups_admin_router())
        .nest("/admin", admin::admin_routes());

    // Serve the pinned Lovable dashboard while keeping `/api` and websocket
    // routes on this origin. Client-side routes fall back to index.html.
    let static_dir = std::env::var("OP_WEB_STATIC_DIR")
        .unwrap_or_else(|_| "/usr/local/share/op-dbus/dashboard-release".to_string());
    let spa =
        ServeDir::new(&static_dir).fallback(ServeFile::new(format!("{static_dir}/index.html")));

    let router = router.fallback_service(spa);
    // The page's gRPC-Web calls go to the door through op-web's own TLS
    // client, so the browser never handles the door's certificate.
    let router = match crate::door_proxy::DoorProxy::from_env() {
        Ok(proxy) => router.layer(axum::middleware::from_fn_with_state(
            proxy,
            crate::door_proxy::door_connector,
        )),
        Err(error) => {
            tracing::error!(%error, "door connector disabled");
