pub mod admin;
#[allow(dead_code)]
pub mod chat;
#[allow(dead_code)]
pub mod llm;

/// Create the complete router with all routes
pub fn create_router(state: Arc<AppState>) -> Router {
    // CORS configuration
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
