// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// Minimal append-only Merkle-root anchor for the etched index experiment.
/// Off-chain: etched.index-entry/1 JSON leaves, sha256-chained per entry,
/// keccak256 Merkle tree over the 32-byte leaf digests.
/// On-chain: this contract records roots only. No PII, no identity data.
contract EtchedAnchor {
    struct Anchor {
        uint64 blockNumber;
        uint64 timestamp;
        bool exists;
    }

    mapping(bytes32 => Anchor) private _anchors;
    uint256 public anchorCount;

    event Anchored(bytes32 indexed root, uint256 timestamp, string label);

    /// Record `root`. Re-anchoring the same root is a no-op (still emits).
    function anchor(bytes32 root, string calldata label) external {
        if (!_anchors[root].exists) {
            _anchors[root] = Anchor({
                blockNumber: uint64(block.number),
                timestamp: uint64(block.timestamp),
                exists: true
            });
            anchorCount += 1;
        }
        emit Anchored(root, block.timestamp, label);
    }

    /// Look up when (and whether) `root` was anchored.
    function lookup(bytes32 root)
        external
        view
        returns (bool exists, uint256 blockNumber, uint256 timestamp)
    {
        Anchor memory a = _anchors[root];
        return (a.exists, a.blockNumber, a.timestamp);
    }
}

