import { createHash } from "node:crypto";
import solc from "solc";
import Ganache from "ganache";
import { ethers } from "ethers";
import { readFileSync } from "node:fs";

const sha256hex = (s) => createHash("sha256").update(s, "utf8").digest("hex");
const canon = (o) => JSON.stringify(o);

// 1. Build three chained etched.index-entry/1 leaves (canonical JSON, sha256 chain).
const t0 = "2026-11-01T00:00:00.000Z";
const entries = [];
let prev = "0".repeat(64);
for (let i = 0; i < 3; i++) {
  const e = {
    format: "etched.index-entry/1",
    seq: i,
    prev_hash: prev,
    kind: ["attestation", "contract", "transaction"][i],
    artifact: { chain_id: 84532, ref: "0x" + "ab".repeat(20), description: "experiment leaf " + i },
    identity: { session_id: "00000000-0000-4000-8000-000000000000", genesis: "11".repeat(32) },
    receipt: {
      operation_id: "00000000-0000-4000-8000-00000000000" + i,
      event_hash: "22".repeat(32),
      plugin: "experiment",
      method: "anchor_experiment",
      required_capability: "none",
    },
    created_at: t0,
  };
  const raw = canon(e);
  prev = sha256hex(raw);
  entries.push({ entry: e, digest: prev });
}
console.log("leaves:", entries.map((x) => x.digest.slice(0, 12)).join(" "));

// 2. Merkle root: keccak256 over concatenated 32-byte leaf digests (binary Merkle).
function merkleRoot(leaves) {
  let level = leaves.map((h) => Buffer.from(h, "hex"));
  while (level.length > 1) {
    const next = [];
    for (let i = 0; i < level.length; i += 2) {
      const l = level[i], r = i + 1 < level.length ? level[i + 1] : level[i];
      next.push(Buffer.from(ethers.keccak256(Buffer.concat([l, r])).slice(2), "hex"));
    }
    level = next;
  }
  return "0x" + level[0].toString("hex");
}
const root = merkleRoot(entries.map((x) => x.digest));
console.log("root:", root);

// 3. Compile Anchor.sol.
const input = {
  language: "Solidity",
  sources: { "Anchor.sol": { content: readFileSync("Anchor.sol", "utf8") } },
  settings: { outputSelection: { "*": { "*": ["abi", "evm.bytecode.object"] } } },
};
const out = JSON.parse(solc.compile(JSON.stringify(input)));
if (out.errors) for (const e of out.errors) if (e.severity === "error") throw new Error(e.formattedMessage);
const c = out.contracts["Anchor.sol"]["EtchedAnchor"];

// 4. Local chain (ganache in-process; prefunded throwaway test accounts only).
const server = Ganache.server({ logging: { quiet: true } });
const provider = new ethers.JsonRpcProvider(await server.listen(8545));
const signer = await provider.getSigner(0);
const addr = await signer.getAddress();
console.log("deployer:", addr);

// 5. Deploy, anchor, lookup, verify event.
const factory = new ethers.ContractFactory(c.abi, c.evm.bytecode.object, signer);
const contract = await factory.deploy();
await contract.waitForDeployment();
console.log("contract:", await contract.getAddress());
const tx = await contract.anchor(root, "etched-index/1 experiment");
const rc = await tx.wait();
console.log("anchor tx:", rc.hash, "block:", rc.blockNumber);
const [exists, bn, ts] = await contract.lookup(root);
console.log("lookup:", JSON.stringify({ exists, blockNumber: bn.toString(), timestamp: ts.toString() }));
const ev = rc.logs.map((l) => { try { return contract.interface.parseLog(l); } catch { return null; } }).find(Boolean);
console.log("event:", ev?.name, ev?.args[0], ev?.args[2]);
if (!exists || ev?.args[0].toLowerCase() !== root.toLowerCase()) throw new Error("MISMATCH");
const [exists2] = await contract.lookup("0x" + "00".repeat(32));
console.log("unknown root exists:", exists2);
await server.close();
console.log("EXPERIMENT OK");

